/// The Arabic typeface the printed quotation carries with it.
///
/// A Windows install cannot be assumed to have an Arabic system font, and the
/// document must never reach for a CDN: an on-premise machine may have no
/// internet at all. So the font travels inside the program - embedded in the
/// page itself as a `data:` URI ({@link NASKH_FONT_FACE}) - and Chromium writes
/// the same outlines into the PDF, where they are subsetted and embedded, so
/// the file looks identical on a machine that has never seen the typeface.
///
/// Noto Naskh Arabic, Copyright 2022 The Noto Project Authors, licensed under
/// the SIL Open Font License 1.1. The licence ships with the program as
/// backend/OFL-NotoNaskhArabic.txt and a copy is kept in docs/fonts/.
/// These are Fontsource's Arabic-block subsets, byte for byte
/// (@fontsource/noto-naskh-arabic, files/noto-naskh-arabic-arabic-400-normal.woff2
/// and ...-700-normal.woff2). Do not hand-edit; regenerate from the same files.
export const KAYAN_FONT_FAMILY = 'Kayan Naskh';

/// The regular weight, base64 of the .woff2 so it can travel in the HTML.
const NASKH_REGULAR =
  '';

/// The bold weight: headings and totals are set in it, and a browser asked to
/// fake bold from the regular outline would thicken the Arabic joins.
const NASKH_BOLD =
  '';

/// The `@font-face` rules that make both weights available to the browser
/// doing the printing. No URL is loaded from anywhere: the sources are the
/// two `data:` URIs above.
export const NASKH_FONT_FACE = `
@font-face {
  font-family: '${KAYAN_FONT_FAMILY}';
  src: url(data:font/woff2;base64,${NASKH_REGULAR}) format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: block;
}
@font-face {
  font-family: '${KAYAN_FONT_FAMILY}';
  src: url(data:font/woff2;base64,${NASKH_BOLD}) format('woff2');
  font-weight: 700;
  font-style: normal;
  font-display: block;
}
`;
